module mipi_csi2_receiver (
    input logic clk,
    input logic rst_n,

    // MIPI D-PHY interface
    input logic [3:0] data_lane_p [0:3],      // 4 data lanes
    input logic [3:0] data_lane_n [0:3],
    input logic clk_lane_p,
    input logic clk_lane_n,
    input logic lp_mode,                       // Low power mode indicator

    // Protocol decoding
    output logic [15:0] pixel_data [0:3][0:255], // 4 lanes of pixel data
    output logic [7:0] line_length,
    output logic [15:0] frame_width,
    output logic [15:0] frame_height,
    output logic [3:0] data_type,               // RAW8, RAW10, RGB565, YUV422, etc.
    output logic [1:0] virtual_channel,
    output logic frame_start,
    output logic frame_end,
    output logic line_valid,
    output logic data_valid,

    // Error detection
    output logic ecc_error,
    output logic crc_error,
    output logic sync_error,

    // Statistics
    output logic [31:0] frame_count,
    output logic [31:0] line_count,
    output logic [31:0] byte_count
);

typedef enum logic [4:0] {
    IDLE,
    LP_STATE,
    HS_START,
    SYNC_PATTERN,
    ECC_CHECK,
    PH_HEADER,
    PH_DATA_TYPE,
    PH_WORD_COUNT,
    PH_ECC,
    PAYLOAD_DATA,
    CRC_CHECK,
    LINE_END,
    FRAME_START,
    FRAME_END,
    ERROR_RECOVERY,
    WAIT_HS_TRAIL,
    LP_11_STATE
} state_t;

state_t state, next_state;
logic [31:0] word_count;
logic [15:0] pixel_count [0:3];
logic [7:0] lane_data [0:3];
logic [3:0] lane_align;
logic [5:0] ecc_calc;
logic [5:0] ecc_recv;
logic [15:0] crc_calc;
logic [15:0] crc_recv;
logic [31:0] packet_data [0:255];
logic [2:0] lane_index;
logic sync_detected;
logic [7:0] sync_pattern;

// CSI-2 sync codes
parameter SYNC_CODE = 8'hB8;
parameter BLANKING_CODE = 8'h00;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        word_count <= 32'b0;
        lane_index <= 3'b0;
        pixel_count[0] <= 16'b0;
        pixel_count[1] <= 16'b0;
        pixel_count[2] <= 16'b0;
        pixel_count[3] <= 16'b0;
        frame_count <= 32'b0;
        line_count <= 32'b0;
        byte_count <= 32'b0;
        crc_calc <= 16'hFFFF;

        for (int i = 0; i < 4; i++)
            for (int j = 0; j < 256; j++)
                pixel_data[i][j] <= 16'b0;
    end else begin
        state <= next_state;

        case (state)
            HS_START: begin
                // Deserialize lane data
                for (int i = 0; i < 4; i++) begin
                    lane_data[i] <= {data_lane_p[i], data_lane_n[i]};
                end
            end

            SYNC_PATTERN: begin
                sync_pattern <= lane_data[0];
                sync_detected <= (lane_data[0] == SYNC_CODE);
            end

            PH_HEADER: begin
                packet_data[word_count] <= {lane_data[3], lane_data[2],
                                           lane_data[1], lane_data[0]};
                word_count <= word_count + 1;
            end

            PH_DATA_TYPE: begin
                data_type <= lane_data[0][3:0];
                virtual_channel <= lane_data[0][5:4];
            end

            PH_WORD_COUNT: begin
                word_count <= {lane_data[1], lane_data[0]};
            end

            PH_ECC: begin
                // Calculate ECC (simplified Hamming code)
                ecc_calc <= 6'b0;
                for (int i = 0; i < 24; i++) begin
                    // ECC calculation logic
                end
                ecc_recv <= lane_data[0][5:0];

                if (ecc_calc != ecc_recv)
                    ecc_error <= 1'b1;
            end

            PAYLOAD_DATA: begin
                if (word_count > 0) begin
                    // Distribute data across lanes
                    for (int lane = 0; lane < 4; lane++) begin
                        case (data_type)
                            4'b0010: begin  // RAW10
                                pixel_data[lane][pixel_count[lane]] <=
                                    {lane_data[lane][7:0], 2'b0};
                                pixel_count[lane] <= pixel_count[lane] + 1;
                            end

                            4'b0111: begin  // RGB565
                                pixel_data[lane][pixel_count[lane]] <=
                                    {lane_data[lane*2 +: 16]};
                                pixel_count[lane] <= pixel_count[lane] + 1;
                                lane_index <= lane_index + 1;
                            end

                            4'b1010: begin  // YUV422 8-bit
                                pixel_data[lane][pixel_count[lane]] <=
                                    {lane_data[lane][7:0], lane_data[lane][7:0]};
                                pixel_count[lane] <= pixel_count[lane] + 1;
                            end
                        endcase
                    end

                    word_count <= word_count - 1;
                    byte_count <= byte_count + 4;

                    // Update CRC
                    crc_calc <= crc_calc ^ {lane_data[3], lane_data[2],
                                           lane_data[1], lane_data[0]};
                end
            end

            CRC_CHECK: begin
                crc_recv <= {lane_data[1], lane_data[0]};
                if (crc_calc != crc_recv)
                    crc_error <= 1'b1;
            end

            LINE_END: begin
                line_valid <= 1'b1;
                line_length <= pixel_count[0][7:0];
                line_count <= line_count + 1;

                for (int i = 0; i < 4; i++)
                    pixel_count[i] <= 16'b0;
            end

            FRAME_START: begin
                frame_start <= 1'b1;
                frame_count <= frame_count + 1;
                line_count <= 32'b0;
            end

            FRAME_END: begin
                frame_end <= 1'b1;
                frame_height <= line_count[15:0];
            end
        endcase
    end
end

always_comb begin
    next_state = state;
    data_valid = (state == PAYLOAD_DATA);

    case (state)
        IDLE: begin
            if (!lp_mode) begin
                next_state = LP_STATE;
            end
        end

        LP_STATE: begin
            if (clk_lane_p && !clk_lane_n)  // Clock rising
                next_state = HS_START;
        end

        HS_START: begin
            next_state = SYNC_PATTERN;
        end

        SYNC_PATTERN: begin
            if (sync_detected) begin
                next_state = PH_HEADER;
            end else if (lane_data[0] == BLANKING_CODE) begin
                next_state = LINE_END;
            end else begin
                sync_error <= 1'b1;
                next_state = ERROR_RECOVERY;
            end
        end

        PH_HEADER: begin
            next_state = PH_DATA_TYPE;
        end

        PH_DATA_TYPE: begin
            next_state = PH_WORD_COUNT;
        end

        PH_WORD_COUNT: begin
            next_state = PH_ECC;
        end

        PH_ECC: begin
            if (ecc_error)
                next_state = ERROR_RECOVERY;
            else begin
                case (data_type)
                    4'b0000: next_state = FRAME_START;  // Frame start code
                    4'b0001: next_state = FRAME_END;    // Frame end code
                    4'b0010, 4'b0111, 4'b1010: next_state = PAYLOAD_DATA;
                    default: next_state = WAIT_HS_TRAIL;
                endcase
            end
        end

        PAYLOAD_DATA: begin
            if (word_count == 0)
                next_state = CRC_CHECK;
        end

        CRC_CHECK: begin
            next_state = WAIT_HS_TRAIL;
        end

        LINE_END: begin
            next_state = WAIT_HS_TRAIL;
        end

        FRAME_START: begin
            frame_start <= 1'b0;
            next_state = WAIT_HS_TRAIL;
        end

        FRAME_END: begin
            frame_end <= 1'b0;
            next_state = WAIT_HS_TRAIL;
        end

        WAIT_HS_TRAIL: begin
            if (lp_mode)
                next_state = LP_11_STATE;
        end

        LP_11_STATE: begin
            if (!lp_mode)
                next_state = HS_START;
            else
                next_state = IDLE;
        end

        ERROR_RECOVERY: begin
            if (lp_mode)
                next_state = IDLE;
        end
    endcase
end

endmodule

module pcie_tlp_processor (
    input logic clk,
    input logic rst_n,
    input logic [63:0] tlp_header [0:3],     // 4 DW TLP header
    input logic [31:0] payload_data [0:255], // Payload data
    input logic [7:0] payload_length,
    input logic tlp_valid,
    input logic [11:0] credits_available,     // Flow control credits
    input logic [2:0] traffic_class,
    output logic [63:0] processed_header [0:3],
    output logic tlp_forward,
    output logic [1:0] tlp_type,               // 00:MRd,01:MWr,10:Cpl,11:CplD
    output logic [9:0] requester_id,
    output logic [7:0] tag,
    output logic [3:0] first_be,               // First DW byte enable
    output logic [3:0] last_be,                // Last DW byte enable
    output logic credit_consumed,
    output logic [11:0] credits_remaining
);

typedef enum logic [3:0] {
    IDLE,
    PARSE_HEADER,
    CHECK_CREDITS,
    MEMORY_READ,
    MEMORY_WRITE,
    COMPLETION,
    COMPLETION_DATA,
    CHECK_ADDRESS_ALIGN,
    PROCESS_PAYLOAD,
    UPDATE_CREDITS,
    FORWARD_PACKET,
    REJECT_PACKET,
    WAIT_CREDITS
} state_t;

state_t state, next_state;
logic [63:0] header [0:3];
logic [31:0] address;
logic [9:0] req_id;
logic [7:0] packet_tag;
logic [6:0] dw_count;
logic [11:0] required_credits;
logic [1:0] fmt_type;
logic [4:0] tlp_length;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        for (int i = 0; i < 4; i++)
            header[i] <= 64'b0;
        req_id <= 10'b0;
        packet_tag <= 8'b0;
        dw_count <= 7'b0;
        required_credits <= 12'b0;
    end else begin
        state <= next_state;

        case (state)
            IDLE: begin
                if (tlp_valid) begin
                    for (int i = 0; i < 4; i++)
                        header[i] <= tlp_header[i];
                end
            end

            PARSE_HEADER: begin
                // Parse TLP header fields
                fmt_type <= header[0][63:56];  // Fmt and Type fields
                tlp_length <= header[0][54:48]; // Length field (in DW)
                req_id <= header[1][31:22];     // Requester ID
                packet_tag <= header[1][21:16];  // Tag

                // Calculate required credits (1 credit = 4 DW)
                required_credits <= (tlp_length + 3) >> 2;
            end

            PROCESS_PAYLOAD: begin
                if (dw_count < tlp_length) begin
                    // Process payload data
                    dw_count <= dw_count + 1;
                end
            end

            UPDATE_CREDITS: begin
                credits_remaining <= credits_available - required_credits;
            end
        endcase
    end
end

always_comb begin
    next_state = state;
    tlp_forward = 1'b0;
    credit_consumed = 1'b0;
    credits_remaining = credits_available;
    processed_header = header;
    tlp_type = 2'b00;
    requester_id = req_id;
    tag = packet_tag;

    case (state)
        IDLE: begin
            if (tlp_valid) begin
                next_state = PARSE_HEADER;
            end
        end

        PARSE_HEADER: begin
            case (fmt_type[6:5])  // Fmt field
                2'b00: begin  // 3 DW header, no data
                    next_state = CHECK_CREDITS;
                end
                2'b01: begin  // 4 DW header, no data
                    next_state = CHECK_CREDITS;
                end
                2'b10: begin  // 3 DW header, with data
                    next_state = PROCESS_PAYLOAD;
                end
                2'b11: begin  // 4 DW header, with data
                    next_state = PROCESS_PAYLOAD;
                end
            endcase
        end

        CHECK_CREDITS: begin
            if (required_credits <= credits_available) begin
                case (fmt_type[4:0])  // Type field
                    5'b00000: begin  // Memory Read
                        next_state = MEMORY_READ;
                    end
                    5'b00001: begin  // Memory Write
                        next_state = MEMORY_WRITE;
                    end
                    5'b01010: begin  // Completion
                        next_state = COMPLETION;
                    end
                    5'b01011: begin  // Completion with Data
                        next_state = COMPLETION_DATA;
                    end
                    default: begin
                        next_state = REJECT_PACKET;
                    end
                endcase
            end else begin
                next_state = WAIT_CREDITS;
            end
        end

        MEMORY_READ: begin
            tlp_type = 2'b00;
            address = {header[2][31:0], header[3][31:0]};
            first_be = header[1][15:12];
            last_be = header[1][11:8];
            next_state = UPDATE_CREDITS;
        end

        MEMORY_WRITE: begin
            tlp_type = 2'b01;
            address = {header[2][31:0], header[3][31:0]};
            first_be = header[1][15:12];
            last_be = header[1][11:8];
            next_state = PROCESS_PAYLOAD;
        end

        COMPLETION: begin
            tlp_type = 2'b10;
            next_state = UPDATE_CREDITS;
        end

        COMPLETION_DATA: begin
            tlp_type = 2'b11;
            next_state = PROCESS_PAYLOAD;
        end

        PROCESS_PAYLOAD: begin
            if (dw_count >= tlp_length - 1) begin
                case (tlp_type)
                    2'b00, 2'b10: next_state = UPDATE_CREDITS;
                    2'b01, 2'b11: next_state = FORWARD_PACKET;
                endcase
            end
        end

        UPDATE_CREDITS: begin
            credit_consumed = 1'b1;
            next_state = FORWARD_PACKET;
        end

        FORWARD_PACKET: begin
            tlp_forward = 1'b1;
            next_state = IDLE;
        end

        WAIT_CREDITS: begin
            // Wait for credits to become available
            if (required_credits <= credits_available)
                next_state = MEMORY_READ;
        end

        REJECT_PACKET: begin
            // Reject unsupported TLP types
            next_state = IDLE;
        end
    endcase
end

endmodule

module ddr4_controller (
    input logic clk,
    input logic rst_n,
    input logic [31:0] address,
    input logic [7:0] burst_length,
    input logic read_request,
    input logic write_request,
    input logic [511:0] write_data,
    output logic [511:0] read_data,
    output logic read_valid,
    output logic write_done,
    output logic ready,

    // DDR4 physical interface
    output logic [16:0] ddr_addr,
    output logic [2:0] ddr_bank,
    output logic ddr_ras_n,
    output logic ddr_cas_n,
    output logic ddr_we_n,
    output logic ddr_cke,
    output logic ddr_cs_n,
    output logic [1:0] ddr_bg,  // Bank group
    output logic ddr_act_n,      // Activate
    output logic [3:0] ddr_dm,   // Data mask
    inout logic [31:0] ddr_dq    // Data bus
);

typedef enum logic [5:0] {
    IDLE,
    PRECHARGE_ALL,
    PRECHARGE_BANK,
    ACTIVATE_ROW,
    READ_BURST,
    WRITE_BURST,
    READ_PRECHARGE,
    WRITE_PRECHARGE,
    AUTO_REFRESH,
    REFRESH_WAIT,
    ZQ_CALIBRATION,
    POWER_DOWN_ENTRY,
    POWER_DOWN_EXIT,
    SELF_REFRESH,
    SELF_REFRESH_EXIT,
    MODE_REG_WRITE,
    MODE_REG_READ,
    WAIT_TRCD,           // RAS to CAS delay
    WAIT_TRP,            // Precharge to activate delay
    WAIT_TRAS,           // Active to precharge delay
    WAIT_TRC,            // Active to active delay
    WAIT_TRFC,           // Refresh cycle time
    WAIT_TWR,            // Write recovery time
    WAIT_TWTR,           // Write to read delay
    WAIT_TCCD,           // CAS to CAS delay
    BANK_CONFLICT,
    ROW_CONFLICT,
    SCHEDULE_REFRESH
} state_t;

state_t state, next_state;
logic [15:0] row_address [0:3][0:7];  // Row address per bank group and bank
logic [2:0] active_bank [0:3];        // Currently active bank per bank group
logic [15:0] active_row [0:3];         // Currently active row per bank group
logic bank_active [0:3][0:7];          // Bank active flag
logic [31:0] refresh_timer;
logic [7:0] timing_counter;
logic [1:0] current_bg;
logic [2:0] current_bank;
logic [15:0] current_row;
logic [2:0] col_address;
logic refresh_request;
logic [1:0] bg_decode;
logic [2:0] bank_decode;

// Address decoding
assign bg_decode = address[17:16];      // Bank group
assign bank_decode = address[15:13];     // Bank
assign current_row = address[31:18];      // Row address
assign col_address = address[12:10];      // Column address

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        refresh_timer <= 32'b0;
        timing_counter <= 8'b0;

        for (int bg = 0; bg < 4; bg++) begin
            active_bank[bg] <= 3'b0;
            active_row[bg] <= 16'b0;
            for (int bank = 0; bank < 8; bank++) begin
                bank_active[bg][bank] <= 1'b0;
                row_address[bg][bank] <= 16'b0;
            end
        end
    end else begin
        state <= next_state;

        case (state)
            ACTIVATE_ROW: begin
                row_address[current_bg][current_bank] <= current_row;
                active_row[current_bg] <= current_row;
                active_bank[current_bg] <= current_bank;
                bank_active[current_bg][current_bank] <= 1'b1;
            end

            PRECHARGE_BANK: begin
                bank_active[current_bg][current_bank] <= 1'b0;
            end

            PRECHARGE_ALL: begin
                for (int bg = 0; bg < 4; bg++)
                    for (int bank = 0; bank < 8; bank++)
                        bank_active[bg][bank] <= 1'b0;
            end

            WAIT_TRCD, WAIT_TRP, WAIT_TRAS, WAIT_TRC,
            WAIT_TRFC, WAIT_TWR, WAIT_TWTR, WAIT_TCCD: begin
                timing_counter <= timing_counter + 1;
            end

            AUTO_REFRESH: begin
                refresh_timer <= 32'b0;
            end

            default: begin
                refresh_timer <= refresh_timer + 1;
            end
        endcase
    end
end

always_comb begin
    next_state = state;
    ready = (state == IDLE);
    read_valid = 1'b0;
    write_done = 1'b0;
    ddr_cke = 1'b1;
    ddr_cs_n = 1'b0;
    ddr_act_n = 1'b1;
    ddr_ras_n = 1'b1;
    ddr_cas_n = 1'b1;
    ddr_we_n = 1'b1;
    ddr_bg = current_bg;
    ddr_bank = current_bank;
    ddr_addr = {1'b0, current_row};  // Row/Column address

    // Decode current access
    current_bg = bg_decode;
    current_bank = bank_decode;

    // Refresh request every 7.8us (at 400MHz, ~3120 cycles)
    refresh_request = (refresh_timer > 3120);

    case (state)
        IDLE: begin
            if (refresh_request) begin
                next_state = SCHEDULE_REFRESH;
            end else if (read_request || write_request) begin
                // Check if target bank is active
                if (bank_active[current_bg][current_bank]) begin
                    if (row_address[current_bg][current_bank] == current_row) begin
                        // Row already active
                        if (read_request)
                            next_state = READ_BURST;
                        else
                            next_state = WRITE_BURST;
                    end else begin
                        // Row conflict
                        next_state = ROW_CONFLICT;
                    end
                end else begin
                    // Bank not active
                    next_state = ACTIVATE_ROW;
                end
            end
        end

        ACTIVATE_ROW: begin
            ddr_act_n = 1'b0;
            ddr_addr = {1'b0, current_row};
            next_state = WAIT_TRCD;
        end

        WAIT_TRCD: begin
            // tRCD = 12-15 cycles
            if (timing_counter >= 12) begin
                if (read_request)
                    next_state = READ_BURST;
                else
                    next_state = WRITE_BURST;
            end
        end

        READ_BURST: begin
            ddr_ras_n = 1'b1;
            ddr_cas_n = 1'b0;
            ddr_we_n = 1'b1;
            ddr_addr = {3'b0, col_address, 4'b0};

            if (burst_length == 8) begin
                next_state = READ_PRECHARGE;
            end
        end

        WRITE_BURST: begin
            ddr_ras_n = 1'b1;
            ddr_cas_n = 1'b0;
            ddr_we_n = 1'b0;
            ddr_addr = {3'b0, col_address, 4'b0};
            ddr_dq = write_data[31:0];  // Write first 32 bits

            if (burst_length == 8) begin
                next_state = WRITE_PRECHARGE;
            end
        end

        READ_PRECHARGE: begin
            // Auto precharge after read
            next_state = PRECHARGE_BANK;
        end

        WRITE_PRECHARGE: begin
            // Need write recovery time
            next_state = WAIT_TWR;
        end

        WAIT_TWR: begin
            // tWR = 12 cycles
            if (timing_counter >= 12)
                next_state = PRECHARGE_BANK;
        end

        PRECHARGE_BANK: begin
            ddr_ras_n = 1'b0;
            ddr_cas_n = 1'b1;
            ddr_we_n = 1'b0;
            ddr_addr[10] = 1'b0;  // Single bank precharge
            next_state = WAIT_TRP;
        end

        WAIT_TRP: begin
            // tRP = 12 cycles
            if (timing_counter >= 12) begin
                if (read_request)
                    read_valid = 1'b1;
                else
                    write_done = 1'b1;
                next_state = IDLE;
            end
        end

        ROW_CONFLICT: begin
            next_state = PRECHARGE_BANK;
        end

        BANK_CONFLICT: begin
            // Need to precharge other bank in same bank group
            next_state = PRECHARGE_BANK;
        end

        SCHEDULE_REFRESH: begin
            if (!bank_active[current_bg][current_bank]) begin
                next_state = AUTO_REFRESH;
            end else begin
                // Need to precharge active banks first
                next_state = PRECHARGE_ALL;
            end
        end

        PRECHARGE_ALL: begin
            ddr_ras_n = 1'b0;
            ddr_cas_n = 1'b1;
            ddr_we_n = 1'b0;
            ddr_addr[10] = 1'b1;  // All banks precharge
            next_state = WAIT_TRP;
        end

        AUTO_REFRESH: begin
            ddr_ras_n = 1'b0;
            ddr_cas_n = 1'b0;
            ddr_we_n = 1'b1;
            next_state = REFRESH_WAIT;
        end

        REFRESH_WAIT: begin
            // tRFC = 160-350 cycles depending on density
            if (timing_counter >= 160)
                next_state = IDLE;
        end

        ZQ_CALIBRATION: begin
            // ZQ calibration sequence
            next_state = IDLE;
        end

        MODE_REG_WRITE: begin
            // Load mode register
            next_state = IDLE;
        end

        MODE_REG_READ: begin
            // Read mode register
            next_state = IDLE;
        end
    endcase
end

endmodule

module image_signal_processor (
    input logic clk,
    input logic rst_n,

    // Bayer pattern input (RAW sensor data)
    input logic [9:0] bayer_pixel,
    input logic [15:0] frame_width,
    input logic [15:0] frame_height,
    input logic hsync,
    input logic vsync,
    input logic pixel_valid,

    // Configuration registers
    input logic [15:0] white_balance_r,
    input logic [15:0] white_balance_g,
    input logic [15:0] white_balance_b,
    input logic [7:0] gamma_lut [0:255],
    input logic [2:0] bayer_pattern,  // 0: RGGB, 1: GRBG, 2: GBRG, 3: BGGR

    // RGB output (24-bit)
    output logic [7:0] rgb_r,
    output logic [7:0] rgb_g,
    output logic [7:0] rgb_b,
    output logic rgb_valid,
    output logic frame_sync,
    output logic line_sync
);

//-------------------------------------------------------------------------
// Pipeline Stage 1: Bayer Demosaic
//-------------------------------------------------------------------------
typedef struct {
    logic [9:0] pixels [0:2][0:2];  // 3x3 window
    logic [15:0] x_count;
    logic [15:0] y_count;
    logic hsync_d1;
    logic vsync_d1;
    logic valid_d1;
} stage1_t;

stage1_t stage1_reg, stage1_next;
logic [9:0] line_buffer [0:2047][0:1];  // 2-line buffer for 3x3 window

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage1_reg.x_count <= 16'b0;
        stage1_reg.y_count <= 16'b0;
        stage1_reg.hsync_d1 <= 1'b0;
        stage1_reg.vsync_d1 <= 1'b0;
        stage1_reg.valid_d1 <= 1'b0;

        for (int i = 0; i < 2048; i++)
            for (int j = 0; j < 2; j++)
                line_buffer[i][j] <= 10'b0;
    end else begin
        stage1_reg <= stage1_next;

        // Update line buffer
        if (pixel_valid) begin
            line_buffer[stage1_reg.x_count][0] <= bayer_pixel;
            line_buffer[stage1_reg.x_count][1] <= line_buffer[stage1_reg.x_count][0];
        end
    end
end

always_comb begin
    stage1_next = stage1_reg;
    stage1_next.hsync_d1 = hsync;
    stage1_next.vsync_d1 = vsync;
    stage1_next.valid_d1 = pixel_valid;

    if (pixel_valid) begin
        stage1_next.x_count = stage1_reg.x_count + 1;

        // Update 3x3 window
        stage1_next.pixels[0][0] = stage1_reg.pixels[0][1];
        stage1_next.pixels[0][1] = stage1_reg.pixels[0][2];
        stage1_next.pixels[0][2] = line_buffer[stage1_reg.x_count][1];

        stage1_next.pixels[1][0] = stage1_reg.pixels[1][1];
        stage1_next.pixels[1][1] = stage1_reg.pixels[1][2];
        stage1_next.pixels[1][2] = line_buffer[stage1_reg.x_count][0];

        stage1_next.pixels[2][0] = stage1_reg.pixels[2][1];
        stage1_next.pixels[2][1] = stage1_reg.pixels[2][2];
        stage1_next.pixels[2][2] = bayer_pixel;

        if (stage1_reg.x_count == frame_width - 1) begin
            stage1_next.x_count = 16'b0;
            stage1_next.y_count = stage1_reg.y_count + 1;
        end
    end
end

//-------------------------------------------------------------------------
// Stage 1 Output: Demosaic Interpolation
//-------------------------------------------------------------------------
logic [15:0] r_interp, g_interp, b_interp;
logic stage1_valid;

always_comb begin
    stage1_valid = stage1_reg.valid_d1 &&
                   stage1_reg.x_count > 0 &&
                   stage1_reg.x_count < frame_width - 1 &&
                   stage1_reg.y_count > 0 &&
                   stage1_reg.y_count < frame_height - 1;

    if (stage1_valid) begin
        case (bayer_pattern)
            3'b000: begin  // RGGB
                r_interp = (stage1_reg.pixels[0][0] + stage1_reg.pixels[0][2] +
                           stage1_reg.pixels[2][0] + stage1_reg.pixels[2][2]) >> 2;
                g_interp = (stage1_reg.pixels[0][1] + stage1_reg.pixels[1][0] +
                           stage1_reg.pixels[1][2] + stage1_reg.pixels[2][1]) >> 2;
                b_interp = stage1_reg.pixels[1][1];
            end

            3'b001: begin  // GRBG
                g_interp = (stage1_reg.pixels[0][0] + stage1_reg.pixels[0][2] +
                           stage1_reg.pixels[2][0] + stage1_reg.pixels[2][2]) >> 2;
                r_interp = (stage1_reg.pixels[0][1] + stage1_reg.pixels[1][0] +
                           stage1_reg.pixels[1][2] + stage1_reg.pixels[2][1]) >> 2;
                b_interp = stage1_reg.pixels[1][1];
            end

            3'b010: begin  // GBRG
                g_interp = (stage1_reg.pixels[0][0] + stage1_reg.pixels[0][2] +
                           stage1_reg.pixels[2][0] + stage1_reg.pixels[2][2]) >> 2;
                b_interp = (stage1_reg.pixels[0][1] + stage1_reg.pixels[1][0] +
                           stage1_reg.pixels[1][2] + stage1_reg.pixels[2][1]) >> 2;
                r_interp = stage1_reg.pixels[1][1];
            end

            3'b011: begin  // BGGR
                b_interp = (stage1_reg.pixels[0][0] + stage1_reg.pixels[0][2] +
                           stage1_reg.pixels[2][0] + stage1_reg.pixels[2][2]) >> 2;
                g_interp = (stage1_reg.pixels[0][1] + stage1_reg.pixels[1][0] +
                           stage1_reg.pixels[1][2] + stage1_reg.pixels[2][1]) >> 2;
                r_interp = stage1_reg.pixels[1][1];
            end
        endcase
    end else begin
        r_interp = 16'b0;
        g_interp = 16'b0;
        b_interp = 16'b0;
    end
end

//-------------------------------------------------------------------------
// Pipeline Stage 2: White Balance
//-------------------------------------------------------------------------
typedef struct {
    logic [23:0] rgb_data;  // 8-bit per channel after white balance
    logic hsync_d2;
    logic vsync_d2;
    logic valid_d2;
} stage2_t;

stage2_t stage2_reg, stage2_next;
logic [23:0] wb_r, wb_g, wb_b;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage2_reg.valid_d2 <= 1'b0;
        stage2_reg.hsync_d2 <= 1'b0;
        stage2_reg.vsync_d2 <= 1'b0;
        stage2_reg.rgb_data <= 24'b0;
    end else begin
        stage2_reg <= stage2_next;
    end
end

always_comb begin
    stage2_next = stage2_reg;
    stage2_next.hsync_d2 = stage1_reg.hsync_d1;
    stage2_next.vsync_d2 = stage1_reg.vsync_d1;
    stage2_next.valid_d2 = stage1_valid;

    // Apply white balance gains
    wb_r = (r_interp * white_balance_r) >> 8;
    wb_g = (g_interp * white_balance_g) >> 8;
    wb_b = (b_interp * white_balance_b) >> 8;

    // Clip to 8-bit
    stage2_next.rgb_data[23:16] = (wb_r[15:0] > 16'hFF00) ? 8'hFF : wb_r[15:8];
    stage2_next.rgb_data[15:8]  = (wb_g[15:0] > 16'hFF00) ? 8'hFF : wb_g[15:8];
    stage2_next.rgb_data[7:0]   = (wb_b[15:0] > 16'hFF00) ? 8'hFF : wb_b[15:8];
end

//-------------------------------------------------------------------------
// Pipeline Stage 3: Gamma Correction
//-------------------------------------------------------------------------
typedef struct {
    logic [7:0] r_gamma;
    logic [7:0] g_gamma;
    logic [7:0] b_gamma;
    logic hsync_d3;
    logic vsync_d3;
    logic valid_d3;
} stage3_t;

stage3_t stage3_reg, stage3_next;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage3_reg.valid_d3 <= 1'b0;
        stage3_reg.hsync_d3 <= 1'b0;
        stage3_reg.vsync_d3 <= 1'b0;
        stage3_reg.r_gamma <= 8'b0;
        stage3_reg.g_gamma <= 8'b0;
        stage3_reg.b_gamma <= 8'b0;
    end else begin
        stage3_reg <= stage3_next;
    end
end

always_comb begin
    stage3_next = stage3_reg;
    stage3_next.hsync_d3 = stage2_reg.hsync_d2;
    stage3_next.vsync_d3 = stage2_reg.vsync_d2;
    stage3_next.valid_d3 = stage2_reg.valid_d2;

    // Apply gamma correction using LUT
    stage3_next.r_gamma = gamma_lut[stage2_reg.rgb_data[23:16]];
    stage3_next.g_gamma = gamma_lut[stage2_reg.rgb_data[15:8]];
    stage3_next.b_gamma = gamma_lut[stage2_reg.rgb_data[7:0]];
end

//-------------------------------------------------------------------------
// Output Stage
//-------------------------------------------------------------------------
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        rgb_r <= 8'b0;
        rgb_g <= 8'b0;
        rgb_b <= 8'b0;
        rgb_valid <= 1'b0;
        frame_sync <= 1'b0;
        line_sync <= 1'b0;
    end else begin
        rgb_r <= stage3_reg.r_gamma;
        rgb_g <= stage3_reg.g_gamma;
        rgb_b <= stage3_reg.b_gamma;
        rgb_valid <= stage3_reg.valid_d3;
        frame_sync <= stage3_reg.vsync_d3;
        line_sync <= stage3_reg.hsync_d3;
    end
end

endmodule

module ethernet_mac_qos (
    input logic clk,
    input logic rst_n,

    // GMII/RGMII interface
    input logic [7:0] gmii_rxd,
    input logic gmii_rx_dv,
    input logic gmii_rx_er,
    output logic [7:0] gmii_txd,
    output logic gmii_tx_en,
    output logic gmii_tx_er,
    input logic gmii_tx_clk,
    input logic gmii_rx_clk,

    // User interface with QoS
    input logic [7:0] tx_data [0:3][0:63],  // 4 priority queues
    input logic [5:0] tx_length [0:3],
    input logic [1:0] tx_queue,
    input logic tx_valid,
    output logic tx_ready,

    output logic [7:0] rx_data [0:63],
    output logic [5:0] rx_length,
    output logic [2:0] rx_priority,           // Extracted priority
    output logic rx_valid,
    output logic rx_error,

    // Statistics
    output logic [31:0] tx_packets [0:3],
    output logic [31:0] rx_packets [0:7],
    output logic [15:0] collisions,
    output logic [15:0] crc_errors
);

typedef enum logic [4:0] {
    // Transmit states
    TX_IDLE,
    TX_PREAMBLE,
    TX_SFD,
    TX_DATA,
    TX_CRC,
    TX_IFG,
    TX_BACKOFF,
    TX_RETRY,
    TX_PAUSE,

    // Receive states
    RX_IDLE,
    RX_PREAMBLE,
    RX_SFD,
    RX_DATA,
    RX_CRC,
    RX_ERROR,

    // QoS scheduling
    QOS_STRICT_PRIORITY,
    QOS_WRR,
    QOS_WRR_UPDATE,
    QOS_TX_SCHEDULE,

    // Flow control
    FLOW_PAUSE_SENT,
    FLOW_PAUSE_RCVD,
    FLOW_XON,
    FLOW_XOFF
} state_t;

state_t tx_state, rx_state, qos_state, next_state;
logic [47:0] src_mac, dst_mac;
logic [15:0] ethertype;
logic [31:0] crc_calc;
logic [6:0] byte_count;
logic [2:0] backoff_count;
logic [9:0] random_seed;
logic carrier_sense;
logic collision_detect;
logic [3:0] wrr_credit [0:3];  // Weighted Round Robin credits
logic [1:0] current_queue;
logic [1:0] next_queue;
logic pause_frame;
logic [15:0] pause_time;

// CRC32 implementation
function [31:0] crc32;
    input [7:0] data;
    input [31:0] crc;
    // Simplified CRC32 - actual implementation would be more complex
    crc32 = crc ^ {24'b0, data};
endfunction

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        tx_state <= TX_IDLE;
        rx_state <= RX_IDLE;
        qos_state <= QOS_STRICT_PRIORITY;
        byte_count <= 7'b0;
        backoff_count <= 3'b0;
        crc_calc <= 32'hFFFFFFFF;
        current_queue <= 2'b0;

        for (int i = 0; i < 4; i++) begin
            tx_packets[i] <= 32'b0;
            wrr_credit[i] <= 4'b1000;  // Initial credits
        end

        for (int i = 0; i < 8; i++)
            rx_packets[i] <= 32'b0;

        collisions <= 16'b0;
        crc_errors <= 16'b0;
    end else begin
        tx_state <= next_state;
        rx_state <= next_state;
        qos_state <= next_state;

        case (tx_state)
            TX_DATA: begin
                if (byte_count < tx_length[current_queue] - 1)
                    byte_count <= byte_count + 1;
                crc_calc <= crc32(tx_data[current_queue][byte_count], crc_calc);
            end

            TX_CRC: begin
                // Transmit CRC
                gmii_txd <= ~crc_calc[31:24];  // Send CRC MSB first
                crc_calc <= {crc_calc[23:0], 8'hFF};
            end

            TX_BACKOFF: begin
                random_seed <= random_seed + 1;
                backoff_count <= backoff_count + 1;
            end

            default: begin
                byte_count <= 7'b0;
            end
        endcase

        case (rx_state)
            RX_DATA: begin
                if (gmii_rx_dv) begin
                    rx_data[byte_count] <= gmii_rxd;
                    byte_count <= byte_count + 1;
                    crc_calc <= crc32(gmii_rxd, crc_calc);
                end
            end

            RX_CRC: begin
                if (crc_calc != 32'hDEBB20E3)  // Valid CRC residue
                    crc_errors <= crc_errors + 1;
            end

            default: begin
                byte_count <= 7'b0;
                crc_calc <= 32'hFFFFFFFF;
            end
        endcase

        case (qos_state)
            QOS_WRR_UPDATE: begin
                for (int i = 0; i < 4; i++)
                    wrr_credit[i] <= wrr_credit[i] + 1;
            end
        endcase
    end
end

always_comb begin
    next_state = tx_state;  // Default
    tx_ready = (tx_state == TX_IDLE);
    rx_valid = 1'b0;
    rx_error = 1'b0;

module ethernet_crc32_pipelined (
    input logic clk,
    input logic rst_n,
    input logic [7:0] data_in,
    input logic data_valid,
    input logic start_frame,
    input logic end_frame,
    output logic [31:0] crc_out,
    output logic crc_valid,
    output logic crc_error
);

//-------------------------------------------------------------------------
// State enumeration
//-------------------------------------------------------------------------
typedef enum logic [1:0] {
    IDLE,
    CALC,
    FINALIZE,
    CHECK
} state_t;

//-------------------------------------------------------------------------
// CRC32 Constants (Ethernet polynomial: 0x04C11DB7)
//-------------------------------------------------------------------------
parameter CRC32_POLY = 32'h04C11DB7;
parameter CRC32_INIT = 32'hFFFFFFFF;
parameter CRC32_RESIDUE = 32'hDEBB20E3;

//-------------------------------------------------------------------------
// Sequential logic: State and pipeline registers
//-------------------------------------------------------------------------
state_t state_reg, state_next;
logic [31:0] crc_reg, crc_next;
logic [31:0] crc_pipe1, crc_pipe2;
logic [7:0] data_pipe1, data_pipe2;
logic valid_pipe1, valid_pipe2;
logic start_pipe1, start_pipe2;
logic end_pipe1, end_pipe2;
logic [2:0] byte_count_reg, byte_count_next;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state_reg <= IDLE;
        crc_reg <= CRC32_INIT;
        crc_pipe1 <= 32'b0;
        crc_pipe2 <= 32'b0;
        data_pipe1 <= 8'b0;
        data_pipe2 <= 8'b0;
        valid_pipe1 <= 1'b0;
        valid_pipe2 <= 1'b0;
        start_pipe1 <= 1'b0;
        start_pipe2 <= 1'b0;
        end_pipe1 <= 1'b0;
        end_pipe2 <= 1'b0;
        byte_count_reg <= 3'b0;
    end else begin
        state_reg <= state_next;
        crc_reg <= crc_next;
        byte_count_reg <= byte_count_next;

        // Pipeline stage 1
        crc_pipe1 <= crc_reg;
        data_pipe1 <= data_in;
        valid_pipe1 <= data_valid;
        start_pipe1 <= start_frame;
        end_pipe1 <= end_frame;

        // Pipeline stage 2
        crc_pipe2 <= crc_pipe1;
        data_pipe2 <= data_pipe1;
        valid_pipe2 <= valid_pipe1;
        start_pipe2 <= start_pipe1;
        end_pipe2 <= end_pipe1;
    end
end

//-------------------------------------------------------------------------
// CRC32 calculation function (combinational)
//-------------------------------------------------------------------------
function automatic [31:0] crc32_byte;
    input [31:0] crc;
    input [7:0] data;
    logic [31:0] new_crc;
    logic [31:0] poly;
begin
    new_crc = crc ^ {24'b0, data};
    poly = CRC32_POLY;

    for (int i = 0; i < 8; i++) begin
        if (new_crc[0])
            new_crc = (new_crc >> 1) ^ poly;
        else
            new_crc = (new_crc >> 1);
    end

    crc32_byte = new_crc;
end
endfunction

//-------------------------------------------------------------------------
// Pipeline stage 1 combinational logic
//-------------------------------------------------------------------------
logic [31:0] crc_stage1_out;
logic [31:0] crc_stage1_init;
logic stage1_valid;

always_comb begin
    // Stage 1 CRC calculation
    if (start_pipe1)
        crc_stage1_init = CRC32_INIT;
    else
        crc_stage1_init = crc_pipe1;

    if (valid_pipe1)
        crc_stage1_out = crc32_byte(crc_stage1_init, data_in);
    else
        crc_stage1_out = crc_stage1_init;

    stage1_valid = valid_pipe1;
end

//-------------------------------------------------------------------------
// Pipeline stage 2 combinational logic
//-------------------------------------------------------------------------
logic [31:0] crc_stage2_out;
logic [31:0] crc_stage2_final;
logic stage2_start, stage2_end;

always_comb begin
    // Stage 2 CRC calculation
    if (start_pipe2)
        crc_stage2_out = crc32_byte(CRC32_INIT, data_pipe2);
    else if (valid_pipe2)
        crc_stage2_out = crc32_byte(crc_pipe2, data_pipe2);
    else
        crc_stage2_out = crc_pipe2;

    // Final XOR
    crc_stage2_final = ~crc_stage2_out;

    stage2_start = start_pipe2;
    stage2_end = end_pipe2;
end

//-------------------------------------------------------------------------
// Main FSM combinational logic
//-------------------------------------------------------------------------
always_comb begin
    state_next = state_reg;
    crc_next = crc_reg;
    byte_count_next = byte_count_reg;
    crc_out = 32'b0;
    crc_valid = 1'b0;
    crc_error = 1'b0;

    case (state_reg)
        IDLE: begin
            if (start_frame) begin
                state_next = CALC;
                crc_next = CRC32_INIT;
                byte_count_next = 3'b0;
            end
        end

        CALC: begin
            // Update CRC with pipelined output
            crc_next = crc_stage2_out;

            if (valid_pipe2)
                byte_count_next = byte_count_reg + 1;

            if (end_pipe2) begin
                state_next = FINALIZE;
                crc_next = crc_stage2_final;
            end
        end

        FINALIZE: begin
            crc_out = crc_reg;
            crc_valid = 1'b1;
            state_next = CHECK;
        end

        CHECK: begin
            // Check against expected residue
            if (crc_reg == CRC32_RESIDUE)
                crc_error = 1'b0;
            else
                crc_error = 1'b1;

            if (!data_valid)
                state_next = IDLE;
        end
    endcase
end

endmodule

module usb3_protocol_layer (
    input logic clk,
    input logic rst_n,
    input logic [31:0] packet_data [0:15],   // Packet data (max 16 DW)
    input logic [4:0] packet_length,
    input logic packet_valid,
    input logic [3:0] endpoint,
    input logic [2:0] device_address,
    input logic direction,                     // 0: OUT, 1: IN
    input logic setup_stage,

    // Link Management
    input logic [1:0] link_status,             // From PHY
    input logic link_up,
    output logic [1:0] link_command,

    // Protocol outputs
    output logic [31:0] rx_data [0:15],
    output logic [4:0] rx_length,
    output logic rx_valid,
    output logic [3:0] rx_endpoint,
    output logic [2:0] rx_device,
    output logic [1:0] transaction_type,       // 00:SETUP,01:DATA,10:STATUS,11:PING
    output logic [2:0] sequence_number,
    output logic data_xfer_complete,
    output logic link_power_state               // 0:L0,1:L1,2:L2
);

typedef enum logic [5:0] {
    // Link states
    LINK_RESET,
    LINK_POLLING,
    LINK_U0,              // Active
    LINK_U1,              // Sleep
    LINK_U2,              // Deep sleep
    LINK_U3,              // Suspend
    LINK_RECOVERY,
    LINK_HOT_RESET,

    // Protocol states
    PROTOCOL_IDLE,
    PROTOCOL_SETUP,
    PROTOCOL_DATA_OUT,
    PROTOCOL_DATA_IN,
    PROTOCOL_STATUS,
    PROTOCOL_PING,
    PROTOCOL_NYET,
    PROTOCOL_ERDY,

    // Packet handling
    PACKET_HEADER,
    PACKET_DATA,
    PACKET_CRC,
    PACKET_ACK,
    PACKET_NACK,
    PACKET_STALL,
    PACKET_NOTIFY,

    // Flow control
    FLOW_CREDIT_UPDATE,
    FLOW_WAIT,
    FLOW_TIMEOUT,

    // Error handling
    ERROR_RETRY,
    ERROR_RECOVERY,
    ERROR_TIMEOUT
} state_t;

state_t link_state, protocol_state, next_state;
logic [2:0] seq_num;
logic [3:0] credit_count [0:15];  // Credits per endpoint
logic [15:0] retry_counter;
logic [31:0] timeout_counter;
logic [4:0] data_phase;
logic burst_mode;
logic [2:0] retry_count;

// Packet type encoding
typedef enum logic [4:0] {
    PTYPE_SETUP     = 5'b00001,
    PTYPE_DATA      = 5'b00010,
    PTYPE_ACK       = 5'b00100,
    PTYPE_NACK      = 5'b01000,
    PTYPE_STALL     = 5'b10000,
    PTYPE_ERDY      = 5'b11000,
    PTYPE_PING      = 5'b10100,
    PTYPE_NOTIFY    = 5'b10010
} packet_type_t;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        link_state <= LINK_RESET;
        protocol_state <= PROTOCOL_IDLE;
        seq_num <= 3'b0;
        data_phase <= 5'b0;
        retry_count <= 3'b0;
        retry_counter <= 16'b0;
        timeout_counter <= 32'b0;

        for (int i = 0; i < 16; i++)
            credit_count[i] <= 4'b1111;  // Initial credits
    end else begin
        link_state <= next_state;
        protocol_state <= next_state;

        case (link_state)
            LINK_U0: begin
                // Update sequence number
                case (protocol_state)
                    PACKET_ACK: seq_num <= seq_num + 1;
                    PACKET_NACK: retry_count <= retry_count + 1;
                endcase
            end

            LINK_U1, LINK_U2: begin
                // Power saving states
                if (timeout_counter < 32'hFFFFFFFF)
                    timeout_counter <= timeout_counter + 1;
            end

            LINK_RECOVERY: begin
                retry_counter <= retry_counter + 1;
            end
        endcase

        case (protocol_state)
            FLOW_CREDIT_UPDATE: begin
                credit_count[endpoint] <= credit_count[endpoint] - 1;
            end

            ERROR_TIMEOUT: begin
                timeout_counter <= timeout_counter + 1;
            end
        endcase
    end
end

always_comb begin
    next_state = protocol_state;
    link_command = 2'b00;
    rx_valid = 1'b0;
    data_xfer_complete = 1'b0;
    link_power_state = 2'b00;
    transaction_type = 2'b00;
    sequence_number = seq_num;

    // Link state machine
    case (link_state)
        LINK_RESET: begin
            link_command = 2'b01;  // Reset
            if (link_up)
                next_state = LINK_POLLING;
        end

        LINK_POLLING: begin
            link_command = 2'b10;  // Polling
            if (link_status == 2'b11)
                next_state = LINK_U0;
        end

        LINK_U0: begin
            link_power_state = 2'b00;
            // Protocol handling in U0 state
            case (protocol_state)
                PROTOCOL_IDLE: begin
                    if (packet_valid) begin
                        case ({setup_stage, direction})
                            2'b10: next_state = PROTOCOL_SETUP;
                            2'b00: next_state = PROTOCOL_DATA_OUT;
                            2'b01: next_state = PROTOCOL_DATA_IN;
                        endcase
                    end

                    // Power management
                    if (timeout_counter > 10000)  // Idle timeout
                        next_state = LINK_U1;
                end

                PROTOCOL_SETUP: begin
                    transaction_type = 2'b00;
                    next_state = PACKET_HEADER;
                end

                PROTOCOL_DATA_OUT: begin
                    transaction_type = 2'b01;
                    if (credit_count[endpoint] > 0)
                        next_state = PACKET_HEADER;
                    else
                        next_state = FLOW_WAIT;
                end

                PROTOCOL_DATA_IN: begin
                    transaction_type = 2'b01;
                    next_state = PACKET_HEADER;
                end

                PROTOCOL_STATUS: begin
                    transaction_type = 2'b10;
                    next_state = PACKET_HEADER;
                end

                PROTOCOL_PING: begin
                    transaction_type = 2'b11;
                    next_state = PACKET_HEADER;
                end

                PACKET_HEADER: begin
                    // Send packet header
                    case (transaction_type)
                        2'b00: rx_data[0] = {PTYPE_SETUP, device_address, endpoint, seq_num};
                        2'b01: rx_data[0] = {PTYPE_DATA, device_address, endpoint, seq_num};
                        2'b10: rx_data[0] = {PTYPE_ERDY, device_address, endpoint, seq_num};
                        2'b11: rx_data[0] = {PTYPE_PING, device_address, endpoint, seq_num};
                    endcase

                    if (packet_length > 0)
                        next_state = PACKET_DATA;
                    else
                        next_state = PACKET_CRC;
                end

                PACKET_DATA: begin
                    // Transfer data payload
                    for (int i = 0; i < packet_length; i++)
                        rx_data[i+1] = packet_data[i];

                    data_phase <= data_phase + 1;
                    if (data_phase >= packet_length - 1)
                        next_state = PACKET_CRC;
                end

                PACKET_CRC: begin
                    // CRC generation and check
                    next_state = PACKET_ACK;
                end

                PACKET_ACK: begin
                    rx_valid = 1'b1;
                    rx_length = packet_length;
                    rx_endpoint = endpoint;
                    rx_device = device_address;

                    case (transaction_type)
                        2'b00: next_state = PROTOCOL_STATUS;
                        2'b01: begin
                            if (data_phase == 5'b11111)  // Max burst
                                next_state = PROTOCOL_STATUS;
                            else if (direction)
                                next_state = PROTOCOL_DATA_IN;
                            else
                                next_state = PROTOCOL_DATA_OUT;
                        end
                        2'b10: begin
                            data_xfer_complete = 1'b1;
                            next_state = PROTOCOL_IDLE;
                        end
                    endcase
                end

                PACKET_NACK: begin
                    if (retry_count < 3)
                        next_state = PACKET_HEADER;
                    else
                        next_state = ERROR_RETRY;
                end

                PACKET_STALL: begin
                    next_state = PROTOCOL_IDLE;
                end

                FLOW_WAIT: begin
                    if (credit_count[endpoint] > 0)
                        next_state = PROTOCOL_DATA_OUT;
                    else if (timeout_counter > 1000)
                        next_state = PROTOCOL_PING;
                end

                FLOW_CREDIT_UPDATE: begin
                    next_state = PROTOCOL_DATA_OUT;
                end

                ERROR_RETRY: begin
                    if (retry_counter < 100)
                        next_state = PACKET_HEADER;
                    else
                        next_state = ERROR_RECOVERY;
                end

                ERROR_RECOVERY: begin
                    link_command = 2'b11;  // Recovery
                    next_state = LINK_RECOVERY;
                end

                ERROR_TIMEOUT: begin
                    if (timeout_counter > 10000)
                        next_state = LINK_RECOVERY;
                end
            endcase
        end

        LINK_U1: begin
            link_power_state = 2'b01;
            link_command = 2'b01;  // Sleep
            if (packet_valid)
                next_state = LINK_RECOVERY;
        end

        LINK_U2: begin
            link_power_state = 2'b10;
            if (packet_valid)
                next_state = LINK_RECOVERY;
        end

        LINK_U3: begin
            link_power_state = 2'b11;
            // Wake on activity
        end

        LINK_RECOVERY: begin
            if (link_status == 2'b11)
                next_state = LINK_U0;
            else if (retry_counter > 1000)
                next_state = LINK_HOT_RESET;
        end

        LINK_HOT_RESET: begin
            link_command = 2'b00;  // Reset
            next_state = LINK_RESET;
        end
    endcase
end

endmodule

module axi_stream_fifo_monitor (
    input logic s_axis_aclk,           // Slave clock (write domain)
    input logic m_axis_aclk,           // Master clock (read domain)
    input logic s_axis_aresetn,        // Slave reset
    input logic m_axis_aresetn,        // Master reset

    // Slave interface (write)
    input logic [63:0] s_axis_tdata,
    input logic [7:0] s_axis_tkeep,
    input logic s_axis_tvalid,
    input logic s_axis_tlast,
    output logic s_axis_tready,

    // Master interface (read)
    output logic [63:0] m_axis_tdata,
    output logic [7:0] m_axis_tkeep,
    output logic m_axis_tvalid,
    output logic m_axis_tlast,
    input logic m_axis_tready,

    // Status outputs (synchronous to s_axis_aclk)
    output logic [9:0] fifo_fill_level,
    output logic fifo_empty,
    output logic fifo_full,
    output logic fifo_almost_empty,
    output logic fifo_almost_full,
    output logic [31:0] frame_count,
    output logic [31:0] byte_count,
    output logic overflow_error,
    output logic underflow_error
);

//-------------------------------------------------------------------------
// Parameters
//-------------------------------------------------------------------------
parameter FIFO_DEPTH = 1024;
parameter ALMOST_EMPTY_THRESH = 32;
parameter ALMOST_FULL_THRESH = 992;

//-------------------------------------------------------------------------
// Dual-port RAM declaration
//-------------------------------------------------------------------------
typedef struct packed {
    logic [63:0] data;
    logic [7:0] keep;
    logic last;
} fifo_entry_t;

fifo_entry_t fifo_ram [0:FIFO_DEPTH-1];

//-------------------------------------------------------------------------
// Write domain logic (s_axis_aclk)
//-------------------------------------------------------------------------
logic [9:0] wr_ptr_reg, wr_ptr_next;
logic [9:0] rd_ptr_sync1, rd_ptr_sync2, rd_ptr_sync3;
logic [31:0] frame_count_reg, frame_count_next;
logic [31:0] byte_count_reg, byte_count_next;
logic overflow_reg, overflow_next;

always_ff @(posedge s_axis_aclk or negedge s_axis_aresetn) begin
    if (!s_axis_aresetn) begin
        wr_ptr_reg <= 10'b0;
        frame_count_reg <= 32'b0;
        byte_count_reg <= 32'b0;
        overflow_reg <= 1'b0;
        rd_ptr_sync1 <= 10'b0;
        rd_ptr_sync2 <= 10'b0;
        rd_ptr_sync3 <= 10'b0;
    end else begin
        wr_ptr_reg <= wr_ptr_next;
        frame_count_reg <= frame_count_next;
        byte_count_reg <= byte_count_next;
        overflow_reg <= overflow_next;

        // Synchronize read pointer to write clock domain
        rd_ptr_sync1 <= rd_ptr_reg;
        rd_ptr_sync2 <= rd_ptr_sync1;
        rd_ptr_sync3 <= rd_ptr_sync2;
    end
end

// Write pointer management
logic [9:0] write_space;
assign write_space = (rd_ptr_sync3 > wr_ptr_reg) ?
                     (rd_ptr_sync3 - wr_ptr_reg - 1) :
                     (FIFO_DEPTH - (wr_ptr_reg - rd_ptr_sync3) - 1);

always_comb begin
    wr_ptr_next = wr_ptr_reg;
    frame_count_next = frame_count_reg;
    byte_count_next = byte_count_reg;
    overflow_next = overflow_reg;
    s_axis_tready = (write_space > 0);

    if (s_axis_tvalid && s_axis_tready) begin
        // Write to FIFO
        fifo_ram[wr_ptr_reg].data <= s_axis_tdata;
        fifo_ram[wr_ptr_reg].keep <= s_axis_tkeep;
        fifo_ram[wr_ptr_reg].last <= s_axis_tlast;

        wr_ptr_next = wr_ptr_reg + 1;
        byte_count_next = byte_count_reg + $countones(s_axis_tkeep);

        if (s_axis_tlast)
            frame_count_next = frame_count_reg + 1;
    end

    // Overflow detection
    if (s_axis_tvalid && !s_axis_tready)
        overflow_next = 1'b1;
    else if (overflow_reg && !s_axis_tvalid)
        overflow_next = 1'b0;
end

//-------------------------------------------------------------------------
// Read domain logic (m_axis_aclk)
//-------------------------------------------------------------------------
logic [9:0] rd_ptr_reg, rd_ptr_next;
logic [9:0] wr_ptr_sync1, wr_ptr_sync2, wr_ptr_sync3;
logic underflow_reg, underflow_next;

always_ff @(posedge m_axis_aclk or negedge m_axis_aresetn) begin
    if (!m_axis_aresetn) begin
        rd_ptr_reg <= 10'b0;
        underflow_reg <= 1'b0;
        wr_ptr_sync1 <= 10'b0;
        wr_ptr_sync2 <= 10'b0;
        wr_ptr_sync3 <= 10'b0;
    end else begin
        rd_ptr_reg <= rd_ptr_next;
        underflow_reg <= underflow_next;

        // Synchronize write pointer to read clock domain
        wr_ptr_sync1 <= wr_ptr_reg;
        wr_ptr_sync2 <= wr_ptr_sync1;
        wr_ptr_sync3 <= wr_ptr_sync2;
    end
end

// Read pointer management
logic [9:0] available_data;
assign available_data = (wr_ptr_sync3 >= rd_ptr_reg) ?
                        (wr_ptr_sync3 - rd_ptr_reg) :
                        (FIFO_DEPTH - (rd_ptr_reg - wr_ptr_sync3));

always_comb begin
    rd_ptr_next = rd_ptr_reg;
    underflow_next = underflow_reg;
    m_axis_tvalid = (available_data > 0);
    m_axis_tdata = fifo_ram[rd_ptr_reg].data;
    m_axis_tkeep = fifo_ram[rd_ptr_reg].keep;
    m_axis_tlast = fifo_ram[rd_ptr_reg].last;

    if (m_axis_tready && m_axis_tvalid) begin
        rd_ptr_next = rd_ptr_reg + 1;
    end

    // Underflow detection
    if (m_axis_tready && !m_axis_tvalid)
        underflow_next = 1'b1;
    else if (underflow_reg && m_axis_tvalid)
        underflow_next = 1'b0;
end

//-------------------------------------------------------------------------
// Status calculation (synchronous to s_axis_aclk)
//-------------------------------------------------------------------------
logic [9:0] fill_level;
logic [9:0] rd_ptr_stable;

always_ff @(posedge s_axis_aclk or negedge s_axis_aresetn) begin
    if (!s_axis_aresetn) begin
        fifo_fill_level <= 10'b0;
        fifo_empty <= 1'b1;
        fifo_full <= 1'b0;
        fifo_almost_empty <= 1'b1;
        fifo_almost_full <= 1'b0;
        frame_count <= 32'b0;
        byte_count <= 32'b0;
        overflow_error <= 1'b0;
    end else begin
        // Use synchronized read pointer for stable status
        rd_ptr_stable = rd_ptr_sync3;

        // Calculate fill level
        if (wr_ptr_reg >= rd_ptr_stable)
            fill_level = wr_ptr_reg - rd_ptr_stable;
        else
            fill_level = FIFO_DEPTH - (rd_ptr_stable - wr_ptr_reg);

        fifo_fill_level <= fill_level;
        fifo_empty <= (fill_level == 0);
        fifo_full <= (fill_level == FIFO_DEPTH - 1);
        fifo_almost_empty <= (fill_level <= ALMOST_EMPTY_THRESH);
        fifo_almost_full <= (fill_level >= ALMOST_FULL_THRESH);

        // Update status registers
        frame_count <= frame_count_reg;
        byte_count <= byte_count_reg;
        overflow_error <= overflow_reg;
        underflow_error <= underflow_reg;
    end
end

endmodule

module ethernet_packet_classifier (
    input logic clk,
    input logic rst_n,

    // Packet header input
    input logic [47:0] eth_dst_mac,
    input logic [47:0] eth_src_mac,
    input logic [15:0] eth_type,
    input logic [31:0] ip_src_addr,
    input logic [31:0] ip_dst_addr,
    input logic [7:0] ip_protocol,
    input logic [15:0] l4_src_port,
    input logic [15:0] l4_dst_port,
    input logic header_valid,

    // Classification results
    output logic [15:0] flow_id,
    output logic [7:0] priority,
    output logic [3:0] action,           // 0: DROP, 1: FORWARD, 2: MIRROR, 3: REDIRECT
    output logic [7:0] queue_id,
    output logic [31:0] meter_id,
    output logic classified_valid,

    // Statistics
    output logic [47:0] matched_packets [0:15],
    output logic [47:0] matched_bytes [0:15],
    output logic [31:0] timestamp [0:15]
);

//-------------------------------------------------------------------------
// Parameters and Types
//-------------------------------------------------------------------------
parameter NUM_FLOWS = 16;
parameter STATS_WIDTH = 48;

typedef struct packed {
    logic [47:0] dst_mac;
    logic [47:0] src_mac;
    logic [15:0] eth_type;
    logic [31:0] ip_src;
    logic [31:0] ip_dst;
    logic [7:0] ip_proto;
    logic [15:0] src_port;
    logic [15:0] dst_port;
} packet_key_t;

typedef struct packed {
    logic [15:0] flow_id;
    logic [7:0] priority;
    logic [3:0] action;
    logic [7:0] queue;
    logic [31:0] meter;
    logic valid;
} result_t;

//-------------------------------------------------------------------------
// Match Table Memories
//-------------------------------------------------------------------------
packet_key_t match_table [0:NUM_FLOWS-1];
result_t result_table [0:NUM_FLOWS-1];
logic [47:0] packet_count [0:NUM_FLOWS-1];
logic [47:0] byte_count [0:NUM_FLOWS-1];
logic [31:0] last_seen [0:NUM_FLOWS-1];

//-------------------------------------------------------------------------
// Input Pipeline Stage
//-------------------------------------------------------------------------
packet_key_t key_reg, key_next;
logic key_valid_reg, key_valid_next;
logic [15:0] pkt_len_reg, pkt_len_next;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        key_reg <= '0;
        key_valid_reg <= 1'b0;
        pkt_len_reg <= 16'b0;
    end else begin
        key_reg <= key_next;
        key_valid_reg <= key_valid_next;
        pkt_len_reg <= pkt_len_next;
    end
end

always_comb begin
    key_next = key_reg;
    key_valid_next = key_valid_reg;
    pkt_len_next = pkt_len_reg;

    if (header_valid) begin
        key_next.dst_mac = eth_dst_mac;
        key_next.src_mac = eth_src_mac;
        key_next.eth_type = eth_type;
        key_next.ip_src = ip_src_addr;
        key_next.ip_dst = ip_dst_addr;
        key_next.ip_proto = ip_protocol;
        key_next.src_port = l4_src_port;
        key_next.dst_port = l4_dst_port;
        key_valid_next = 1'b1;
        pkt_len_next = pkt_len_reg + 64; // Approximate packet length
    end else begin
        key_valid_next = 1'b0;
    end
end

//-------------------------------------------------------------------------
// Parallel Match Logic (Combinational)
//-------------------------------------------------------------------------
logic [NUM_FLOWS-1:0] match_vector;
result_t [NUM_FLOWS-1:0] candidate_results;
logic [3:0] best_match_idx;
logic [7:0] best_priority;
logic match_found;

genvar i;
generate
    for (i = 0; i < NUM_FLOWS; i++) begin : match_logic
        always_comb begin
            // Exact match on all fields
            if (key_valid_reg &&
                match_table[i].dst_mac == key_reg.dst_mac &&
                match_table[i].src_mac == key_reg.src_mac &&
                match_table[i].eth_type == key_reg.eth_type &&
                match_table[i].ip_src == key_reg.ip_src &&
                match_table[i].ip_dst == key_reg.ip_dst &&
                match_table[i].ip_proto == key_reg.ip_proto &&
                match_table[i].src_port == key_reg.src_port &&
                match_table[i].dst_port == key_reg.dst_port) begin

                match_vector[i] = 1'b1;
                candidate_results[i] = result_table[i];
            end else begin
                match_vector[i] = 1'b0;
                candidate_results[i] = '0;
            end
        end
    end
endgenerate

//-------------------------------------------------------------------------
// Priority Encoder (Combinational)
//-------------------------------------------------------------------------
always_comb begin
    best_match_idx = 4'b0;
    best_priority = 8'b0;
    match_found = 1'b0;

    for (int i = 0; i < NUM_FLOWS; i++) begin
        if (match_vector[i] && candidate_results[i].priority >= best_priority) begin
            best_match_idx = i;
            best_priority = candidate_results[i].priority;
            match_found = 1'b1;
        end
    end
end

//-------------------------------------------------------------------------
// Result Generation (Combinational)
//-------------------------------------------------------------------------
result_t result_reg, result_next;

always_comb begin
    result_next = result_reg;

    if (match_found) begin
        result_next = candidate_results[best_match_idx];
        result_next.valid = 1'b1;
    end else begin
        result_next.valid = 1'b0;
        result_next.action = 4'd1; // Default FORWARD
        result_next.queue = 8'd0;
        result_next.flow_id = 16'hFFFF; // Unknown flow
    end
end

//-------------------------------------------------------------------------
// Statistics Update Logic (Sequential)
//-------------------------------------------------------------------------
logic stats_update_reg;
logic [3:0] stats_idx_reg;
logic [47:0] packet_count_next [0:NUM_FLOWS-1];
logic [47:0] byte_count_next [0:NUM_FLOWS-1];
logic [31:0] last_seen_next [0:NUM_FLOWS-1];

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stats_update_reg <= 1'b0;
        stats_idx_reg <= 4'b0;

        for (int i = 0; i < NUM_FLOWS; i++) begin
            packet_count[i] <= 48'b0;
            byte_count[i] <= 48'b0;
            last_seen[i] <= 32'b0;
        end
    end else begin
        stats_update_reg <= result_next.valid;
        stats_idx_reg <= best_match_idx;

        // Update statistics memory
        for (int i = 0; i < NUM_FLOWS; i++) begin
            packet_count[i] <= packet_count_next[i];
            byte_count[i] <= byte_count_next[i];
            last_seen[i] <= last_seen_next[i];
        end
    end
end

always_comb begin
    // Default: keep current values
    for (int i = 0; i < NUM_FLOWS; i++) begin
        packet_count_next[i] = packet_count[i];
        byte_count_next[i] = byte_count[i];
        last_seen_next[i] = last_seen[i];
    end

    // Update matched flow statistics
    if (result_next.valid && match_found) begin
        packet_count_next[best_match_idx] = packet_count[best_match_idx] + 1;
        byte_count_next[best_match_idx] = byte_count[best_match_idx] + pkt_len_reg;
        last_seen_next[best_match_idx] = timestamp[best_match_idx] + 1;
    end
end

//-------------------------------------------------------------------------
// Output Pipeline Stage (Sequential)
//-------------------------------------------------------------------------
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        result_reg <= '0;
        flow_id <= 16'b0;
        priority <= 8'b0;
        action <= 4'b0;
        queue_id <= 8'b0;
        meter_id <= 32'b0;
        classified_valid <= 1'b0;
    end else begin
        result_reg <= result_next;
        flow_id <= result_next.flow_id;
        priority <= result_next.priority;
        action <= result_next.action;
        queue_id <= result_next.queue;
        meter_id <= result_next.meter;
        classified_valid <= result_next.valid;
    end
end

//-------------------------------------------------------------------------
// Statistics Output (Combinational)
//-------------------------------------------------------------------------
always_comb begin
    for (int i = 0; i < NUM_FLOWS; i++) begin
        matched_packets[i] = packet_count[i];
        matched_bytes[i] = byte_count[i];
        timestamp[i] = last_seen[i];
    end
end

endmodule

module nand_flash_controller (
    input logic clk,
    input logic rst_n,

    // Host interface
    input logic [31:0] flash_addr,
    input logic [11:0] page_size,           // 512B to 16KB
    input logic read_req,
    input logic write_req,
    input logic erase_req,
    input logic [2047:0] write_data,        // Page data
    output logic [2047:0] read_data,
    output logic read_valid,
    output logic write_done,
    output logic erase_done,
    output logic busy,

    // NAND interface
    output logic [15:0] nand_addr,
    output logic [7:0] nand_cmd,
    inout logic [7:0] nand_data,
    output logic nand_cle,                   // Command latch enable
    output logic nand_ale,                   // Address latch enable
    output logic nand_ce_n,                   // Chip enable
    output logic nand_we_n,                   // Write enable
    output logic nand_re_n,                   // Read enable
    input logic nand_rdy,                     // Ready/Busy
    input logic nand_wp_n,                     // Write protect

    // ECC interface
    output logic [12:0] ecc_parity [0:127],   // BCH parity bits
    input logic [12:0] ecc_correction [0:127],
    input logic [6:0] error_count,
    input logic uncorrectable_error,

    // Bad block management
    output logic [15:0] bad_block_table [0:1023],
    output logic block_erasable,
    output logic wear_level_index
);

typedef enum logic [5:0] {
    IDLE,
    READ_PAGE_CMD,
    READ_ADDR_CYCLE1,
    READ_ADDR_CYCLE2,
    READ_ADDR_CYCLE3,
    READ_ADDR_CYCLE4,
    READ_ADDR_CYCLE5,
    READ_WAIT_RDY,
    READ_DATA_TRANSFER,
    READ_ECC_CALC,
    READ_ECC_CORRECT,
    READ_STATUS,

    WRITE_PAGE_CMD,
    WRITE_ADDR_CYCLE1,
    WRITE_ADDR_CYCLE2,
    WRITE_ADDR_CYCLE3,
    WRITE_ADDR_CYCLE4,
    WRITE_ADDR_CYCLE5,
    WRITE_DATA_TRANSFER,
    WRITE_ECC_GEN,
    WRITE_CONFIRM_CMD,
    WRITE_WAIT_RDY,
    WRITE_STATUS,

    ERASE_BLOCK_CMD,
    ERASE_ADDR_CYCLE1,
    ERASE_ADDR_CYCLE2,
    ERASE_ADDR_CYCLE3,
    ERASE_CONFIRM_CMD,
    ERASE_WAIT_RDY,
    ERASE_STATUS,

    BAD_BLOCK_CHECK,
    BAD_BLOCK_MARK,
    WEAR_LEVELING,
    GARBAGE_COLLECT,

    RESET_CMD,
    RESET_WAIT,
    GET_FEATURES,
    SET_FEATURES,

    ERROR_HANDLING,
    RETRY_OPERATION
} state_t;

state_t state, next_state;
logic [31:0] page_address;
logic [15:0] column_address;
logic [15:0] row_address;
logic [12:0] page_counter;
logic [7:0] status_register;
logic [2:0] retry_count;
logic ecc_enabled;
logic [12:0] generated_parity [0:127];
logic [2047:0] data_buffer;
logic [3:0] addr_cycle_count;

// NAND command codes
parameter CMD_READ_PAGE     = 8'h00;
parameter CMD_READ_CONFIRM  = 8'h30;
parameter CMD_WRITE_PAGE    = 8'h80;
parameter CMD_WRITE_CONFIRM = 8'h10;
parameter CMD_ERASE_BLOCK   = 8'h60;
parameter CMD_ERASE_CONFIRM = 8'hD0;
parameter CMD_READ_STATUS   = 8'h70;
parameter CMD_RESET         = 8'hFF;
parameter CMD_GET_FEATURES  = 8'hEE;
parameter CMD_SET_FEATURES  = 8'hEF;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        page_address <= 32'b0;
        column_address <= 16'b0;
        row_address <= 16'b0;
        page_counter <= 13'b0;
        retry_count <= 3'b0;
        addr_cycle_count <= 4'b0;

        for (int i = 0; i < 128; i++) begin
            ecc_parity[i] <= 13'b0;
            generated_parity[i] <= 13'b0;
        end

    end else begin
        state <= next_state;

        case (state)
            IDLE: begin
                if (read_req || write_req || erase_req) begin
                    page_address <= flash_addr;
                    row_address <= flash_addr[31:16];
                    column_address <= flash_addr[15:0];
                end
            end

            READ_DATA_TRANSFER: begin
                if (page_counter < (page_size >> 3)) begin  // Convert to bytes
                    data_buffer[page_counter*8 +: 8] <= nand_data;
                    page_counter <= page_counter + 1;
                end
            end

            WRITE_DATA_TRANSFER: begin
                if (page_counter < (page_size >> 3)) begin
                    nand_data <= write_data[page_counter*8 +: 8];
                    page_counter <= page_counter + 1;
                end
            end

            READ_ECC_CALC: begin
                // Generate ECC for read data
                for (int i = 0; i < 128; i++) begin
                    generated_parity[i] <= data_buffer[i*16 +: 16] ^
                                          {16{1'b1}};  // Simplified BCH
                end
            end

            WRITE_ECC_GEN: begin
                // Generate ECC parity for write data
                for (int i = 0; i < 128; i++) begin
                    ecc_parity[i] <= write_data[i*16 +: 16] ^
                                    {16{1'b1}};  // Simplified BCH
                end
            end

            BAD_BLOCK_CHECK: begin
                if (bad_block_table[row_address[9:0]] != 0)
                    block_erasable <= 1'b0;
                else
                    block_erasable <= 1'b1;
            end

            WEAR_LEVELING: begin
                wear_level_index <= wear_level_index + 1;
            end
        endcase
    end
end

always_comb begin
    next_state = state;
    busy = (state != IDLE);
    read_valid = 1'b0;
    write_done = 1'b0;
    erase_done = 1'b0;
    read_data = data_buffer;

    // Default NAND interface values
    nand_cle = 1'b0;
    nand_ale = 1'b0;
    nand_ce_n = 1'b0;
    nand_we_n = 1'b1;
    nand_re_n = 1'b1;
    nand_cmd = 8'b0;
    nand_addr = 16'b0;

    case (state)
        IDLE: begin
            if (read_req) begin
                next_state = BAD_BLOCK_CHECK;
            end else if (write_req) begin
                if (!bad_block_table[row_address[9:0]])
                    next_state = WRITE_PAGE_CMD;
                else
                    next_state = ERROR_HANDLING;
            end else if (erase_req) begin
                next_state = ERASE_BLOCK_CMD;
            end
        end

        // Read Operations
        READ_PAGE_CMD: begin
            nand_cle = 1'b1;
            nand_we_n = 1'b0;
            nand_cmd = CMD_READ_PAGE;
            next_state = READ_ADDR_CYCLE1;
        end

        READ_ADDR_CYCLE1: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = column_address[7:0];
            next_state = READ_ADDR_CYCLE2;
            addr_cycle_count = 4'd1;
        end

        READ_ADDR_CYCLE2: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = column_address[15:8];
            next_state = READ_ADDR_CYCLE3;
            addr_cycle_count = 4'd2;
        end

        READ_ADDR_CYCLE3: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = row_address[7:0];
            next_state = READ_ADDR_CYCLE4;
            addr_cycle_count = 4'd3;
        end

        READ_ADDR_CYCLE4: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = row_address[15:8];
            next_state = READ_ADDR_CYCLE5;
            addr_cycle_count = 4'd4;
        end

        READ_ADDR_CYCLE5: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = {8'b0, row_address[23:16]};  // 3rd row cycle if needed
            next_state = READ_WAIT_RDY;
            addr_cycle_count = 4'd5;
        end

        READ_WAIT_RDY: begin
            nand_cmd = CMD_READ_CONFIRM;
            nand_cle = 1'b1;
            nand_we_n = 1'b0;

            if (nand_rdy) begin
                next_state = READ_DATA_TRANSFER;
                page_counter = 13'b0;
            end
        end

        READ_DATA_TRANSFER: begin
            nand_re_n = 1'b0;  // Strobe read
            if (page_counter >= (page_size >> 3) - 1) begin
                next_state = READ_ECC_CALC;
            end
        end

        READ_ECC_CALC: begin
            next_state = READ_ECC_CORRECT;
        end

        READ_ECC_CORRECT: begin
            if (uncorrectable_error) begin
                next_state = ERROR_HANDLING;
            end else if (error_count > 0) begin
                // Apply ECC corrections
                for (int i = 0; i < 128; i++) begin
                    if (ecc_correction[i] != 0)
                        data_buffer[i*16 +: 16] <=
                            data_buffer[i*16 +: 16] ^ ecc_correction[i];
                end
            end
            next_state = READ_STATUS;
        end

        READ_STATUS: begin
            nand_cmd = CMD_READ_STATUS;
            nand_cle = 1'b1;
            nand_we_n = 1'b0;

            status_register = nand_data;
            if (status_register[0]) begin  // Check pass/fail
                read_valid = 1'b1;
                next_state = IDLE;
                rx_packets[0] <= rx_packets[0] + 1;
            end else begin
                if (retry_count < 3)
                    next_state = READ_PAGE_CMD;
                else
                    next_state = ERROR_HANDLING;
            end
        end

        // Write Operations
        WRITE_PAGE_CMD: begin
            nand_cle = 1'b1;
            nand_we_n = 1'b0;
            nand_cmd = CMD_WRITE_PAGE;
            next_state = WRITE_ADDR_CYCLE1;
        end

        WRITE_ADDR_CYCLE1: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = column_address[7:0];
            next_state = WRITE_ADDR_CYCLE2;
        end

        WRITE_ADDR_CYCLE2: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = column_address[15:8];
            next_state = WRITE_ADDR_CYCLE3;
        end

        WRITE_ADDR_CYCLE3: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = row_address[7:0];
            next_state = WRITE_ADDR_CYCLE4;
        end

        WRITE_ADDR_CYCLE4: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = row_address[15:8];
            next_state = WRITE_ADDR_CYCLE5;
        end

        WRITE_ADDR_CYCLE5: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = {8'b0, row_address[23:16]};
            next_state = WRITE_DATA_TRANSFER;
            page_counter = 13'b0;
        end

        WRITE_DATA_TRANSFER: begin
            nand_we_n = 1'b0;
            if (page_counter >= (page_size >> 3) - 1) begin
                next_state = WRITE_ECC_GEN;
            end
        end

        WRITE_ECC_GEN: begin
            next_state = WRITE_CONFIRM_CMD;
        end

        WRITE_CONFIRM_CMD: begin
            nand_cle = 1'b1;
            nand_we_n = 1'b0;
            nand_cmd = CMD_WRITE_CONFIRM;
            next_state = WRITE_WAIT_RDY;
        end

        WRITE_WAIT_RDY: begin
            if (nand_rdy) begin
                next_state = WRITE_STATUS;
            end
        end

        WRITE_STATUS: begin
            nand_cmd = CMD_READ_STATUS;
            nand_cle = 1'b1;
            nand_we_n = 1'b0;

            if (nand_data[0]) begin  // Pass
                write_done = 1'b1;
                tx_packets[0] <= tx_packets[0] + 1;
                next_state = IDLE;
            end else begin
                if (retry_count < 3)
                    next_state = WRITE_PAGE_CMD;
                else begin
                    next_state = BAD_BLOCK_MARK;
                end
            end
        end

        // Erase Operations
        ERASE_BLOCK_CMD: begin
            nand_cle = 1'b1;
            nand_we_n = 1'b0;
            nand_cmd = CMD_ERASE_BLOCK;
            next_state = ERASE_ADDR_CYCLE1;
        end

        ERASE_ADDR_CYCLE1: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = row_address[7:0];
            next_state = ERASE_ADDR_CYCLE2;
        end

        ERASE_ADDR_CYCLE2: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = row_address[15:8];
            next_state = ERASE_ADDR_CYCLE3;
        end

        ERASE_ADDR_CYCLE3: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = {8'b0, row_address[23:16]};
            next_state = ERASE_CONFIRM_CMD;
        end

        ERASE_CONFIRM_CMD: begin
            nand_cle = 1'b1;
            nand_we_n = 1'b0;
            nand_cmd = CMD_ERASE_CONFIRM;
            next_state = ERASE_WAIT_RDY;
        end

        ERASE_WAIT_RDY: begin
            if (nand_rdy) begin
                next_state = ERASE_STATUS;
            end
        end

        ERASE_STATUS: begin
            nand_cmd = CMD_READ_STATUS;
            nand_cle = 1'b1;
            nand_we_n = 1'b0;

            if (nand_data[0]) begin
                erase_done = 1'b1;
                next_state = IDLE;
            end else begin
                next_state = ERROR_HANDLING;
            end
        end

        BAD_BLOCK_CHECK: begin
            if (bad_block_table[row_address[9:0]] == 0)
                next_state = READ_PAGE_CMD;
            else
                next_state = ERROR_HANDLING;
        end

        BAD_BLOCK_MARK: begin
            bad_block_table[row_address[9:0]] <= 16'hFFFF;
            next_state = IDLE;
        end

        WEAR_LEVELING: begin
            // Swap static and dynamic data blocks
            next_state = IDLE;
        end

        GARBAGE_COLLECT: begin
            // Copy valid pages to new block
            next_state = IDLE;
        end

        ERROR_HANDLING: begin
            if (retry_count < 3) begin
                retry_count <= retry_count + 1;
                next_state = RETRY_OPERATION;
            end else begin
                next_state = IDLE;
            end
        end

        RETRY_OPERATION: begin
            next_state = READ_PAGE_CMD;  // Default retry
        end
    endcase
end

endmodule
